import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        double n = sc.nextDouble();

        int num = 0, den = 1;
        double target_ratio = x / y;
        double best_ratio = 0;

        for (int i = 1; i <= (int) n; i++) {
            int lower_bound = (int) Math.floor(target_ratio * i);
            int upper_bound = (int) Math.ceil(target_ratio * i);

            if (Math.abs(target_ratio - (double) lower_bound / i) + 1e-15 < Math.abs(target_ratio - best_ratio)) {
                num = lower_bound;
                den = i;
                best_ratio = (double) lower_bound / i;
            }
            if (Math.abs(target_ratio - (double) upper_bound / i) + 1e-15 < Math.abs(target_ratio - best_ratio)) {
                num = upper_bound;
                den = i;
                best_ratio = (double) upper_bound / i;
            }
        }

        int gcd_value = gcd(num, den);
        System.out.println((num / gcd_value) + "/" + (den / gcd_value));
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
